-- ASB product library seed generated from ASB Compensation Schedule - All Carriers - Level 4 - as of 5-13-2026.xlsx
-- Creates canonical carriers/products plus aliases. Safe to re-run.

CREATE TABLE IF NOT EXISTS crm_carriers (id BIGSERIAL PRIMARY KEY, name TEXT NOT NULL, normalized_name TEXT NOT NULL UNIQUE, scope TEXT NOT NULL DEFAULT 'global', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS crm_carrier_aliases (id BIGSERIAL PRIMARY KEY, carrier_id BIGINT NOT NULL REFERENCES crm_carriers(id) ON DELETE CASCADE, alias_text TEXT NOT NULL, normalized_alias TEXT NOT NULL UNIQUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS crm_products (id BIGSERIAL PRIMARY KEY, carrier_id BIGINT NOT NULL REFERENCES crm_carriers(id) ON DELETE CASCADE, name TEXT NOT NULL, normalized_name TEXT NOT NULL, product_type TEXT, scope TEXT NOT NULL DEFAULT 'global', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(carrier_id, normalized_name));
CREATE TABLE IF NOT EXISTS crm_product_aliases (id BIGSERIAL PRIMARY KEY, product_id BIGINT NOT NULL REFERENCES crm_products(id) ON DELETE CASCADE, alias_text TEXT NOT NULL, normalized_alias TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
ALTER TABLE crm_product_aliases DROP CONSTRAINT IF EXISTS crm_product_aliases_normalized_alias_key;
CREATE UNIQUE INDEX IF NOT EXISTS idx_crm_product_aliases_product_alias ON crm_product_aliases (product_id, normalized_alias);

